class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        map<int, int> ways;
        ways[0] = 1;
        for (int i = 0; i < (int)nums.size(); i++) {
            map<int, int> next;
            for (auto& [sum, c] : ways) {
                next[sum + nums[i]] += c;
                next[sum - nums[i]] += c;
            }
            ways = next;
        }
        return ways.count(target) ? ways[target] : 0;
    }
};
